import sys
import math
from abc import ABC, abstractmethod

class Shape(ABC):
    @abstractmethod
    def getArea(self):
        pass

class Circle(Shape):
    def __init__(self, radius):
        self.radius = radius

    def getArea(self):
        return math.pi * self.radius * self.radius

class Rectangle(Shape):
    def __init__(self, length, width):
        self.length = length
        self.width = width

    def getArea(self):
        return self.length * self.width

def main():
    shapes = []

    for line in sys.stdin:
        parts = line.strip().split()
        if not parts:
            continue

        if parts[0] == 'end':
            break

        shape_type = parts[0].lower()

        if shape_type == 'circle':
            radius = int(parts[1])
            shapes.append(Circle(radius))
        elif shape_type == 'rectangle':
            length = int(parts[1])
            width = int(parts[2])
            shapes.append(Rectangle(length, width))

    total_area = 0
    for shape in shapes:
        total_area += shape.getArea()

    print(int(total_area))

if __name__ == "__main__":
    main()
